from pathlib import Path
import json
out=Path('secret-share-results')
rows=json.loads((out/'summary.json').read_text())['results']
lines=['### 5.3 多终端秘密共享与区域需求聚合','','本实验检验两台服务器分别持有区域请求份额时，网络能否依据批次总需求生成与明文合批相同的下行计划，并测量聚合带来的通信开销。实验沿用 2022 年 2 月 14 日三个历史轨道窗口，将 40 × 40 千米网格划分为 16 个区域，每窗口 64 个请求批次，每批取 1、2、4 或 8 个终端，依次每秒到达一个请求。逐终端组在请求到达后独立调度；两个合批组在末个请求到达后开始发送，最晚发送时刻为首个请求到达后 10 秒。每条消息按 256 字节密文载荷建模，每次波束发送携带整批载荷，一个波束可服务多个区域。','','终端将所属区域编码为 16 维独热向量，在模 2³² 的整数环上生成两份加法份额。每份掩码由系统安全随机源生成。两个逻辑服务器分别求和，再合并批次总数。三组共享区域请求和覆盖条件。实验在同一进程模拟不串通的服务器，未测量网络传输时延、密钥管理、实际加密或空口定位误差。','','| 每批终端数 | 方案 | 送达率 | 平均等待（秒） | 每条请求下行载荷（字节） | 每条请求上行向量（字节） |','|---:|---|---:|---:|---:|---:|']
for r in rows:
 label={'individual':'逐终端','plain_batch':'明文合批','shared_batch':'秘密共享合批'}[r['mode']]
 lines.append(f"| {r['users']} | {label} | {r['delivery_rate']:.2%} | {r['mean_wait_s']:.2f} | {r['downlink_bytes_per_request']:.2f} | {r['uplink_bytes_per_request']:.0f} |")
lines+=['','明文基线使用 64 字节的完整向量；采用紧凑区域编号时明文请求可以更小。载荷统计不含报头、确认和服务器间通信。','','全部 768 个配对批次中，重构计数和逐次波束调度均与明文合批一致，因此两组合批方案产生相同的可见发送安排。单个服务器接收的均匀随机份额不透露单条区域向量的数值；精确的区域总数仍可能暴露小批次成员的位置，特别是只有一个终端时。','','[实验代码](../secret_share_experiment.py) · [逐批统计](../secret-share-results/batches.csv) · [汇总结果](../secret-share-results/summary.json)','']
(out/'section.md').write_text('\n'.join(lines)+'\n')
